package com.ccb.release.reporting.persistence;
import com.ccb.common.api.PageQuery; import com.ccb.common.api.PageResult; import com.ccb.release.reporting.model.ReleaseAnalyticsModels.Summary; import org.springframework.stereotype.Repository; import java.util.HashMap; import java.util.LinkedHashMap; import java.util.List; import java.util.Map;
@Repository public class ReleaseAnalyticsStore { private final ReleaseAnalyticsMapper mapper; public ReleaseAnalyticsStore(ReleaseAnalyticsMapper mapper){this.mapper=mapper;} public Summary summary(long tenantId,String projectId,Long windowId){Map<String,Object> p=params(tenantId,projectId,windowId);return new Summary(value(mapper.windows(p)),value(mapper.applications(p)),value(mapper.subsystems(p)),value(mapper.units(p)),value(mapper.fileMedia(p)),value(mapper.requirements(p)),group(mapper.versionTypes(p)),group(mapper.results(p)));} public PageResult<Map<String,Object>> drilldown(long tenantId,String projectId,Long windowId,String dimension,String value,PageQuery page){if(dimension!=null&&!dimension.isBlank()&&!List.of("versionType","status","productionResult").contains(dimension))throw new IllegalArgumentException("unsupported dimension");Map<String,Object> p=params(tenantId,projectId,windowId);p.put("dimension",dimension);p.put("value",value);p.put("size",page.size());p.put("offset",(page.page()-1)*page.size());return new PageResult<>(mapper.drilldown(p),value(mapper.drilldownCount(p)),page.page(),page.size());} private static Map<String,Object> params(long tenantId,String projectId,Long windowId){Map<String,Object> p=new HashMap<>();p.put("tenantId",tenantId);p.put("projectId",projectId==null||projectId.isBlank()?null:projectId.trim());p.put("windowId",windowId);return p;} private static long value(Long v){return v==null?0:v;} private static Map<String,Long> group(List<Map<String,Object>> rows){Map<String,Long> result=new LinkedHashMap<>();for(Map<String,Object> row:rows)result.put(String.valueOf(row.get("metric")),((Number)row.get("amount")).longValue());return result;} }
